{"path": "/workspace/team_adjuster.py", "content": "def adjust_team_size():
    return {
        'rules': [
            {
                'condition': 'team_size == 0',
                'action': 'replace',
                'new_value': '5+'
            },
            {
                'condition': 'team_size == 1',
                'action': 'replace',
                'new_value': '5+'
            }
        ],
        'replacements': {
            0: '5+',
            1: '5+',
            '0': '5+',
            '1': '5+'
        },
        'apply': lambda team_size: '5+' if str(team_size).strip() in ('0', '1') else str(team_size)
    }
"}

